  }

  render(material, target = null) {
    const gl = this.gl;
    const entry = this._programFor(material);
    gl.useProgram(entry.prog);
    if (target) {
      gl.bindFramebuffer(gl.FRAMEBUFFER, target.fbo);
      gl.viewport(0, 0, target.width, target.height);
