  float phase = omega * uTime * uTimeScale * uTurbulence;
  float cosP = cos(phase), sinP = sin(phase);
  vec2 rp = vec2(pos.x*cosP - pos.z*sinP, pos.x*sinP + pos.z*cosP);

  float ang = atan(rp.y, rp.x);
  vec3 q = vec3(rp*0.55, pos.y*2.2);

