        float grav = sqrt(max(1.0 - 1.0/sr, 0.02));
        float shift = mix(1.0, dopp * (1.0/grav), uRedshift);

        vec3 shifted = em * shift*shift*shift * mix(1.0, shift, uDopplerShift);
        shifted *= mix(1.0, pow(shift, 2.2), uBeaming*0.65);

