        transmit *= a;
      }
      if (transmit < 0.01){ captured = true; break; }  /* opaque -> stop tracing */
    }

    p = pn; v = vn;
    totalOptical += h;

    if (r > FAR && dot(p, v) > 0.0){
      /* escaped: lensed sky */
      break;
    }
    if (r < uRs*1.02){ captured = true; break; }
  }

