    e[0] = (1 - (yy + zz)) * sx; e[4] = (xy - wz) * sy;       e[8]  = (xz + wy) * sz;
    e[1] = (xy + wz) * sx;       e[5] = (1 - (xx + zz)) * sy; e[9]  = (yz - wx) * sz;
    e[2] = (xz - wy) * sx;       e[6] = (yz + wx) * sy;       e[10] = (1 - (xx + yy)) * sz;
    e[12] = position.x; e[13] = position.y; e[14] = position.z;
